def transform(grid):
    out=[r[:] for r in grid]
    lines=[i for i,r in enumerate(grid) if len(set(r))==1 and r[0]!=0]
    if lines:
        k=lines[0]
        for i in range(k+1,len(out)):
            out[i]=[0]*len(out[i])
    return out

